import { describe, expect, it } from 'vitest';
import { setup } from './helpers';

describe('POST /webhooks rate limiting', () => {
  it('answers 429 with a Retry-After header when a tenant exceeds the limit', async () => {
    const { postWebhook } = setup({ rateLimitMax: 2, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);

    const res = await postWebhook('tenant-a', { type: 'x' });
    expect(res.status).toBe(429);
    expect(res.headers.get('Retry-After')).not.toBeNull();
    expect(Number(res.headers.get('Retry-After'))).toBeGreaterThan(0);
    expect(await res.json()).toMatchObject({ error: 'rate limit exceeded' });
  });

  it('does not affect other tenants', async () => {
    const { postWebhook } = setup({ rateLimitMax: 1, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(429);
    expect((await postWebhook('tenant-b', { type: 'x' })).status).toBe(202);
  });

  it('reads the limit from config', async () => {
    const { postWebhook } = setup({ rateLimitMax: 3, rateLimitWindowMs: 60000 });
    for (let i = 0; i < 3; i += 1) {
      expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    }
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(429);
  });
});

